def transform(g):
    import numpy as np
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    # find marker colors on border
    markers={}
    for i in range(h):
        for j in range(w):
            if i in(0,h-1) or j in(0,w-1):
                if g[i][j] not in (0,5): markers[g[i][j]]=(i,j)
    cols=sorted(markers.values(), key=lambda p:p[1])
    left,right=cols[0],cols[1]
    lc=[c for c,p in markers.items() if p==left][0]
    rc=[c for c,p in markers.items() if p==right][0]
    # find 5 rectangle
    rs=[i for i in range(h) if 5 in g[i]]
    cs=[j for j in range(w) if any(g[i][j]==5 for i in range(h))]
    for i in range(min(rs)+1,max(rs)):
        for j in range(min(cs)+1,max(cs)):
            g[i][j]= lc if (i< (min(rs)+max(rs))/2) == (j< (min(cs)+max(cs))/2) else rc
    return g
